-- ── verification ──────────────────────────────────────────────────────────
do $verify$
declare
  v_tables int;
  v_rows   int;
  v_bad    int;
  v_free   int;
begin
  select count(*) into v_tables from pg_tables where schemaname = 'public' and tablename like 'ref\_rmth\_%';
  if v_tables <> 14 then
    raise exception '0176: expected 14 ref_rmth_ tables, found %', v_tables;
  end if;

  -- every table has RLS, two policies, the four standard triggers, and rows
  select count(*) into v_bad
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relname like 'ref\_rmth\_%' and c.relkind = 'r'
     and (not c.relrowsecurity
          or (select count(*) from pg_policy p where p.polrelid = c.oid) <> 2
          or (select count(*) from pg_trigger tg where tg.tgrelid = c.oid and not tg.tgisinternal) <> 4);
  if v_bad <> 0 then
    raise exception '0176: % ref_rmth_ tables are missing RLS, a policy or a trigger', v_bad;
  end if;

  execute (
    select 'select ' || string_agg(format('(select count(*) from public.%I)', tablename), ' + ')
      from pg_tables where schemaname = 'public' and tablename in ('ref_rmth_sex', 'ref_rmth_age_group', 'ref_rmth_nationality', 'ref_rmth_sector', 'ref_rmth_activity_category', 'ref_rmth_networking_type', 'ref_rmth_joint_partner', 'ref_rmth_training_type', 'ref_rmth_training_topic', 'ref_rmth_stakeholder_type', 'ref_rmth_incubation_service', 'ref_rmth_employability_outcome', 'ref_rmth_placement_type', 'ref_rmth_work_status'))
    into v_rows;
  if v_rows <> 59 then
    raise exception '0176: expected 59 option rows, found %', v_rows;
  end if;

  execute (
    select 'select ' || string_agg(format('(select count(*) from public.%I where allows_free_text)', tablename), ' + ')
      from pg_tables where schemaname = 'public' and tablename in ('ref_rmth_sex', 'ref_rmth_age_group', 'ref_rmth_nationality', 'ref_rmth_sector', 'ref_rmth_activity_category', 'ref_rmth_networking_type', 'ref_rmth_joint_partner', 'ref_rmth_training_type', 'ref_rmth_training_topic', 'ref_rmth_stakeholder_type', 'ref_rmth_incubation_service', 'ref_rmth_employability_outcome', 'ref_rmth_placement_type', 'ref_rmth_work_status'))
    into v_free;
  if v_free <> 3 then
    raise exception '0176: expected 3 free-text options, found %', v_free;
  end if;
end $verify$;
